import sys
import requests
import json
import re

def evaluate_expression(expr):
    try:
        return eval(expr)
    except:
        return 0

def process_template(template_path, output_path):
    with open(template_path, 'r') as f:
        template_lines = f.readlines()

    with open(output_path, 'w') as out_f:
        for line in template_lines:
            line = line.strip()
            if not line:
                continue

            url, expr = line.split(maxsplit=1)
            response = requests.get(url)
            response.raise_for_status()
            data = response.json()

            # Extract all placeholder names from the expression
            placeholder_names = re.findall(r'\{([^}]+)\}', expr)
            placeholder_values = {}

            for name in placeholder_names:
                if name in data:
                    placeholder_values[name] = data[name]
                else:
                    placeholder_values[name] = 0

            # Replace placeholders in the expression
            for name, value in placeholder_values.items():
                expr = expr.replace(f'{{{name}}}', str(value))

            result = evaluate_expression(expr)

            # Format the result without trailing zeros
            if result.is_integer():
                out_f.write(f"{url}\t{int(result)}\n")
            else:
                formatted_result = "{0:.10f}".format(result).rstrip('0').rstrip('.') if '.' in "{0:.10f}".format(result) else str(int(result))
                out_f.write(f"{url}\t{formatted_result}\n")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python feedsum.py <template_file> <output_file>")
        sys.exit(1)

    template_path = sys.argv[1]
    output_path = sys.argv[2]
    process_template(template_path, output_path)
